using CoracaoAnimal.Client;
using CoracaoAnimal.Core;
namespace CoracaoAnimal.Windows;
public sealed class MainForm:Form {
 readonly ApiClient api=new(new Storage());bool busy;
 static Image? BrandLogo(){var assembly=typeof(MainForm).Assembly;var resource=assembly.GetManifestResourceNames().FirstOrDefault(name=>name.EndsWith("Assets.logo.png",StringComparison.OrdinalIgnoreCase));if(resource==null)return null;using var stream=assembly.GetManifestResourceStream(resource);if(stream==null)return null;using var image=Image.FromStream(stream);return new Bitmap(image);}
 readonly FlowLayoutPanel body=new(){Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(38,30,38,30),BackColor=Theme.Beige};
 readonly Label state=new(){Dock=DockStyle.Bottom,Height=48,Padding=new Padding(24,12,0,0),BackColor=Color.White,ForeColor=Theme.Muted};
 public MainForm(){Text="Coração Animal • Adoção responsável";Width=1160;Height=820;MinimumSize=new Size(820,620);Font=new Font("Segoe UI",10);BackColor=Theme.Beige;ForeColor=Theme.Brown;AutoScaleMode=AutoScaleMode.Dpi;var header=new Panel(){Dock=DockStyle.Top,Height=92,BackColor=Theme.Brown};header.Controls.Add(new PictureBox(){Image=BrandLogo(),SizeMode=PictureBoxSizeMode.Zoom,Bounds=new Rectangle(24,10,72,72),AccessibleName="Logo Coração Animal"});header.Controls.Add(new Label(){Text="Coração Animal",ForeColor=Color.White,Font=new Font("Segoe UI",20,FontStyle.Bold),AutoSize=true,Location=new Point(108,18)});header.Controls.Add(new Label(){Text="CUIDAR • ACOLHER • CONECTAR",ForeColor=ColorTranslator.FromHtml("#F5C9B0"),Font=new Font("Segoe UI",9,FontStyle.Bold),AutoSize=true,Location=new Point(110,54)});var menu=new FlowLayoutPanel(){Dock=DockStyle.Top,Height=66,Padding=new Padding(20,10,10,8),BackColor=Color.White,AutoScroll=true,WrapContents=false};foreach(var item in new(string,Func<Task>)[]{("Animais",()=>Catalog()),("Para você",()=>Catalog(true)),("Minhas adoções",Adoptions),("Doações",Donations),("Voluntariado",Volunteer),("Minha conta",Profile),("Entrar",Login)}){var button=Button(item.Item1,item.Item2);Theme.Button(button,true);menu.Controls.Add(button);}Controls.Add(body);Controls.Add(state);Controls.Add(menu);Controls.Add(header);body.SizeChanged+=(_,_)=>ResizeBody();body.ControlAdded+=(_,_)=>ResizeBody();Shown+=async(_,_)=>await Run(async()=>{await api.Initialize();await Catalog();});}
 Button Button(string text,Func<Task> action){var b=new Button(){Text=text,AutoSize=true,Margin=new Padding(4),AccessibleName=text};Theme.Button(b);b.Click+=async(_,_)=>{b.Enabled=false;await Run(action);if(!b.IsDisposed)b.Enabled=true;};return b;}
 async Task Run(Func<Task> work){if(busy)return;busy=true;state.Text="Carregando…";state.ForeColor=Theme.Muted;try{await work();state.Text="Pronto • "+(api.BaseUri?.Host??"configure a conexão");state.ForeColor=Theme.Green;}catch(UnauthorizedAccessException ex){await Login();state.Text=ex.Message;state.ForeColor=Theme.Orange;}catch(Exception ex){state.Text=ex.Message;state.ForeColor=Theme.Orange;MessageBox.Show(this,ex.Message,"Não foi possível concluir",MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{busy=false;}}
 void ResizeBody(){var width=Math.Max(160,body.ClientSize.Width-body.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth-8);foreach(Control control in body.Controls){if(control is TextBox or ComboBox)control.Width=Math.Min(620,width);else if(control is Label or CheckBox)control.MaximumSize=new Size(width,0);else if(control is PictureBox)control.Width=Math.Min(500,width);}}
 void Page(string title){while(body.Controls.Count>0)body.Controls[0].Dispose();body.Controls.Add(new Label(){Text="CORAÇÃO ANIMAL",AutoSize=true,Font=new Font("Segoe UI",9,FontStyle.Bold),ForeColor=Theme.Orange,Margin=new Padding(0,0,0,6)});body.Controls.Add(new Label(){Text=title,AutoSize=true,Font=new Font("Segoe UI",26,FontStyle.Bold),ForeColor=Theme.Brown,Margin=new Padding(0,0,0,20)});}
 void Note(string text){body.Controls.Add(new Label(){Text=text,AutoSize=true,MaximumSize=new Size(900,0),ForeColor=Theme.Muted,Margin=new Padding(0,8,0,8)});}
 TextBox Field(string label,string value="",bool password=false){Note(label);var x=new TextBox(){Text=value,Width=620,UseSystemPasswordChar=password,AccessibleName=label,BorderStyle=BorderStyle.FixedSingle};Theme.Field(x);body.Controls.Add(x);return x;}
 ComboBox Choice(string label,string[] items,string? value=null){Note(label);var x=new ComboBox(){Width=620,DropDownStyle=ComboBoxStyle.DropDownList,AccessibleName=label};x.Items.AddRange(items);x.SelectedIndex=Math.Max(0,Array.IndexOf(items,value));Theme.Field(x);body.Controls.Add(x);return x;}
 CheckBox Check(string label){var x=new CheckBox(){Text=label,AutoSize=true,MaximumSize=new Size(850,0)};body.Controls.Add(x);return x;}
 void Photo(AnimalDto animal,int height){var pic=new PictureBox(){Width=500,Height=height,SizeMode=PictureBoxSizeMode.Zoom,AccessibleName="Foto de "+animal.Nome,ErrorImage=null,InitialImage=null};body.Controls.Add(pic);pic.LoadAsync(new Uri(api.BaseUri!,animal.FotoUrl!).AbsoluteUri);}
 void Action(string text,Func<Task> action)=>body.Controls.Add(Button(text,action));
 bool Confirm(string message)=>MessageBox.Show(this,message,"Confirmar",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;

 Task Login(){Page("Bem-vindo de volta");var email=Field("E-mail");var senha=Field("Senha","",true);Action("Entrar",async()=>{await api.Login(email.Text,senha.Text);await Profile();});Action("Criar conta",Register);return Task.CompletedTask;}
 Task Register(){Page("Criar conta");var nome=Field("Nome completo");var email=Field("E-mail");var senha=Field("Senha (mínimo 10 caracteres)","",true);Action("Cadastrar",async()=>{await api.Post<object>("api/auth/cadastro",new Cadastro(nome.Text,email.Text,senha.Text));await api.Login(email.Text,senha.Text);await Profile();});return Task.CompletedTask;}
 async Task Catalog(bool recommend=false,int page=1,string busca="",string especie="",string porte=""){if(recommend)await api.Me();var data=recommend?new Pagina<AnimalDto>(await api.Get<List<AnimalDto>>("api/me/recomendacoes")??[],0,1,12):await api.Get<Pagina<AnimalDto>>($"api/animais?pagina={page}&tamanho=12&busca={Uri.EscapeDataString(busca)}&especie={especie}&porte={porte}");Page(recommend?"Encontre seu companheiro":"Animais para adoção");if(!recommend){var search=Field("Buscar pelo nome",busca);var sp=Choice("Espécie",["","cao","gato"],especie);var size=Choice("Porte",["","pequeno","medio","grande"],porte);Action("Buscar",()=>Catalog(false,1,search.Text,sp.Text,size.Text));}else Note("Afinidade calculada a partir das preferências do seu perfil. A equipe avalia cada adoção.");foreach(var animal in data?.Itens??[]){if(animal.FotoUrl!=null)Photo(animal,190);Note($"{animal.Nome} · {animal.Especie} · {animal.Idade} anos · {animal.Porte} · {animal.Status}"+(animal.Compatibilidade.HasValue?$" · Afinidade {animal.Compatibilidade:0.0}%":""));Action("Conhecer "+animal.Nome,()=>Details(animal.Id));}if(data?.Itens.Count==0)Note("Nenhum animal encontrado. Experimente outros filtros ou volte mais tarde.");if(!recommend&&data!=null){if(page>1)Action("Página anterior",()=>Catalog(false,page-1,busca,especie,porte));if(page*12<data.Total)Action("Próxima página",()=>Catalog(false,page+1,busca,especie,porte));}}
 async Task Details(int id){var a=await api.Get<AnimalDto>($"api/animais/{id}")??throw new Exception("Animal não encontrado.");Page(a.Nome);Note($"{a.Especie} · {a.Raca} · {a.Idade} anos · {a.Porte} · {a.Status}");if(a.FotoUrl!=null)Photo(a,280);Note(a.Descricao);if(a.Status=="disponivel"){var obs=Field("Conte como pretende acolher este animal");var terms=Check("Entendo que esta é uma solicitação, sujeita à avaliação da equipe.");Action("Solicitar adoção",async()=>{await api.Post<object>("api/me/adocoes",new AdocaoInput(id,obs.Text,terms.Checked));await Adoptions();});}}
 async Task Adoptions(){var items=await api.Get<List<AdocaoDto>>("api/me/adocoes")??[];Page("Minhas adoções");if(items.Count==0)Note("Você ainda não solicitou uma adoção.");foreach(var a in items){Note($"{a.AnimalNome} · {a.Status} · {a.CriadoEm.ToLocalTime():d}\n{a.Observacoes}");if(a.Status is "pendente" or "aprovada")Action($"Cancelar solicitação #{a.Id}",async()=>{if(Confirm("Cancelar esta solicitação?")){await api.Post<object>($"api/me/adocoes/{a.Id}/cancelar");await Adoptions();}});}}
 async Task Donations(){var items=await api.Get<List<DoacaoDto>>("api/me/doacoes")??[];Page("Apoie o acolhimento");Note("Este formulário registra uma intenção de doação. Não realiza cobrança. A equipe confirma o recebimento pelo site.");var valor=Field("Valor em reais");var forma=Choice("Forma de pagamento",["pix","transferencia","dinheiro"]);var desc=Field("Observação");var anon=Check("Não divulgar meu nome");Action("Registrar intenção",async()=>{var v=DonationAmount.Parse(valor.Text);await api.Post<object>("api/me/doacoes",new DoacaoInput(v,forma.Text,desc.Text,anon.Checked));await Donations();});foreach(var d in items){Note($"#{d.Id} · {d.Valor:C} · {d.Status} · {d.FormaPagamento}");if(d.Status=="pendente")Action($"Cancelar doação #{d.Id}",async()=>{if(Confirm("Cancelar esta intenção?")){await api.Post<object>($"api/me/doacoes/{d.Id}/cancelar");await Donations();}});}}
 async Task Volunteer(){var v=await api.Get<VoluntarioDto>("api/me/voluntariado");Page("Seja voluntário");Note(v==null?"Cadastre sua disponibilidade para ajudar.":"Situação: "+v.Status);var area=Field("Área de interesse",v?.Area??"");var disp=Field("Dias e horários disponíveis",v?.Disponibilidade??"");Action("Salvar inscrição",async()=>{await api.Put<object>("api/me/voluntariado",new VoluntarioInput(area.Text,disp.Text));await Volunteer();});if(v!=null&&v.Status!="inativo")Action("Desativar inscrição",async()=>{if(Confirm("Desativar sua inscrição?")){await api.Delete("api/me/voluntariado");await Volunteer();}});}
 async Task Profile(){var u=await api.Me()??throw new Exception("Entre para continuar.");Page("Minha conta");Note(u.Email);var nome=Field("Nome completo",u.Nome);var cpf=Field("CPF",u.Cpf??"");var tel=Field("Telefone",u.Telefone);var end=Field("Endereço",u.Endereco);var sp=Choice("Espécie preferida",["cao","gato"],u.EspeciePreferida);var esp=Choice("Espaço disponível",["pequeno","medio","grande"],u.Espaco);var exp=Choice("Experiência",["nenhuma","alguma","muita"],u.Experiencia);Action("Salvar perfil",async()=>{await api.Put<object>("api/me/",new PerfilInput(nome.Text,cpf.Text,tel.Text,end.Text,sp.Text,esp.Text,exp.Text));await Profile();});Action("Alterar senha",Password);Action("Sair",async()=>{await api.Logout();await Login();});}
 Task Password(){Page("Alterar senha");var old=Field("Senha atual","",true);var next=Field("Nova senha (mínimo 10 caracteres)","",true);Action("Salvar nova senha",async()=>{await api.Put<object>("api/me/senha",new SenhaInput(old.Text,next.Text));await api.Forget();await Login();});return Task.CompletedTask;}
}
